/**
 * Bank element schema: the single source of truth for TS types (`z.infer`), the committed JSON schema
 * (`schema/bank-index.schema.json`, generated by `bun run bank:schema`) and runtime validation.
 *
 * Frame of every geometry in the bank (GLB, bboxMm, cells): the wall frame of packages/core —
 * millimetres, x right, y up, z out of the wall towards the room, right-handed (= glTF Y-up, so a GLB
 * loads into three.js without rotation). z = 0 is the wall face of the element; the origin (x = y = 0)
 * is the centre of its anchor cell. See docs/bank.md.
 */
import { z } from 'zod';

export const BANK_SCHEMA_VERSION = 1 as const;

/** Lowercase kebab-case identifier, optionally `/`-separated for category paths. */
export const slugSchema = z
  .string()
  .regex(/^[a-z0-9]+(?:-[a-z0-9]+)*$/, 'expected lowercase kebab-case');
const categoryPath = z.string().regex(/^[a-z0-9]+(?:-[a-z0-9]+)*(?:\/[a-z0-9]+(?:-[a-z0-9]+)*)?$/);
const sha256Hex = z.string().regex(/^[0-9a-f]{64}$/);
const assetPath = z.string().regex(/^(?:glb|thumb|variant)\/[0-9a-f]{16}\.(?:glb|webp)$/);

export const LocalizedTextSchema = z.object({ ru: z.string().min(1), en: z.string().min(1) });
export type LocalizedText = z.infer<typeof LocalizedTextSchema>;

export const Vec3Schema = z.object({ x: z.number(), y: z.number(), z: z.number() });
export type Vec3 = z.infer<typeof Vec3Schema>;

/**
 * Honeycomb cell offset from the anchor cell. `dCol` columns to the right; `dRow2` HALF-rows up
 * (neighbouring columns are staggered by half a row, so `dRow2 ≡ dCol (mod 2)`). In mm the offset is
 * (dCol * colPitch, dRow2 * rowPitch / 2) — independent of the parity of the anchor cell's column.
 */
export const CellOffsetSchema = z
  .object({ dCol: z.number().int(), dRow2: z.number().int() })
  .refine((c) => (c.dRow2 - c.dCol) % 2 === 0, 'dRow2 and dCol must have the same parity');
export type CellOffset = z.infer<typeof CellOffsetSchema>;

export const BboxMmSchema = z.object({ min: Vec3Schema, max: Vec3Schema });
export type BboxMm = z.infer<typeof BboxMmSchema>;

export const FootprintSchema = z.object({
  /** Cells whose centres lie under the element's wall-facing silhouette (always contains {0,0}). */
  cells: z.array(CellOffsetSchema).min(1),
  /** Width of the footprint bounding box in columns / rows (informational, derivable from cells). */
  cols: z.number().int().min(1),
  rows: z.number().int().min(1),
});
export type Footprint = z.infer<typeof FootprintSchema>;

export const MOUNTING_KINDS = ['hex-plug', 'm3-screw', 'clip', 'none'] as const;
export const MountingSchema = z.object({
  /**
   * hex-plug: printed plug that clicks into the honeycomb cell; m3-screw: screwed onto an M3 insert;
   * clip: spring clip over a cell wall; none: not mounted on the wall (panels).
   */
  kind: z.enum(MOUNTING_KINDS),
  /** Cells that carry the attachment, a subset of footprint.cells. */
  cells: z.array(CellOffsetSchema),
});
export type Mounting = z.infer<typeof MountingSchema>;

export const PARAM_UNITS = ['mm', 'count', 'deg'] as const;
export const ParamDefSchema = z
  .object({
    key: z.string().regex(/^[a-z][a-zA-Z0-9]*$/),
    label: LocalizedTextSchema,
    unit: z.enum(PARAM_UNITS),
    min: z.number(),
    max: z.number(),
    default: z.number(),
    step: z.number().positive(),
  })
  .refine((p) => p.min <= p.default && p.default <= p.max, 'default must lie within [min, max]');
export type ParamDef = z.infer<typeof ParamDefSchema>;

export const AssetRefSchema = z.object({
  /** Path relative to the bank assets root; the name is derived from the content hash (immutable). */
  path: assetPath,
  bytes: z.number().int().positive(),
  sha256: sha256Hex,
});
export type AssetRef = z.infer<typeof AssetRefSchema>;

export const AssetsSchema = z.object({
  /** Full-detail GLB, EXT_meshopt_compression. */
  lod0: AssetRefSchema,
  /** Reduced GLB for far / crowded views. Points at the same file as lod0 for tiny meshes. */
  lod1: AssetRefSchema,
  /** 192x192 WebP with alpha. */
  thumbnail: AssetRefSchema,
  triangles: z.object({ lod0: z.number().int().positive(), lod1: z.number().int().positive() }),
});
export type Assets = z.infer<typeof AssetsSchema>;

export const PrintNotesSchema = z.object({
  materials: z.array(z.string()).optional(),
  /** How to lay the part on the bed, e.g. "wall face down". */
  orientation: LocalizedTextSchema.optional(),
  supports: z.boolean().optional(),
  notes: LocalizedTextSchema.optional(),
});
export type PrintNotes = z.infer<typeof PrintNotesSchema>;

export const LICENSE_IDS = [
  'MIT',
  'CC-BY-4.0',
  'CC-BY-NC-4.0',
  'CC-BY-NC-SA-4.0',
  'LicenseRef-Standard-Digital-File',
  'LicenseRef-Unknown',
] as const;
export const LicenseSchema = z.object({
  spdx: z.enum(LICENSE_IDS),
  /** Human wording as observed on the source, kept verbatim for audit. */
  observed: z.string(),
  attribution: z.string(),
  url: z.url().optional(),
  /** May the files be committed to / redistributed from the public repo. false => built locally at setup only. */
  redistributable: z.boolean(),
});
export type License = z.infer<typeof LicenseSchema>;

export const SourceRefSchema = z.object({
  site: z.enum(['printables', 'makerworld', 'thingiverse', 'hsw-project', 'unknown']),
  modelId: z.string().optional(),
  title: z.string().optional(),
  author: z.string().optional(),
  url: z.url().optional(),
  /** File inside the HSW sources tree. */
  file: z.string(),
  /** Object inside a multi-part file (3MF object / STEP solid). */
  partId: z.string().optional(),
  sourceSha256: sha256Hex,
});
export type SourceRef = z.infer<typeof SourceRefSchema>;

export const GeneratorRefSchema = z.object({
  /** Generator file under packages/bank/generators. */
  generator: z.string(),
  part: z.string(),
  version: z.number().int().positive(),
  values: z.record(z.string(), z.number()),
});
export type GeneratorRef = z.infer<typeof GeneratorRefSchema>;

export const ProvenanceSchema = z.object({
  origin: z.enum(['source-file', 'project-original', 'generated']),
  source: SourceRefSchema.optional(),
  generator: GeneratorRefSchema.optional(),
  /**
   * How the wall orientation of the source part was decided: `curated` (set by hand), `auto` (guessed from
   * the wall-facing flat face / plug end — verify before trusting), `generator` (built in the wall frame).
   */
  orientation: z.enum(['curated', 'auto', 'generator']),
  /** Hash of the normalised triangle soup (0.01 mm, translation-invariant) of the source mesh. */
  geometryHash: sha256Hex,
  /** Other source files that hold the same geometry (deduped copies). */
  duplicates: z.array(z.string()),
});
export type Provenance = z.infer<typeof ProvenanceSchema>;

export const DimRangeSchema = z.object({ min: z.number(), max: z.number() });
export type DimRange = z.infer<typeof DimRangeSchema>;

/**
 * Hint for the recogniser/fitter: this element holds objects of `toolClass`. `dims` constrains the
 * object's measured dimensions in mm (keys are class specific, e.g. `shaftDiameter`, `width`).
 */
export const FitsToolSchema = z.object({
  toolClass: slugSchema,
  dims: z.record(z.string(), DimRangeSchema).optional(),
  /** How many objects one element holds. */
  capacity: z.number().int().positive().optional(),
  notes: LocalizedTextSchema.optional(),
});
export type FitsTool = z.infer<typeof FitsToolSchema>;

export const BankElementSchema = z.object({
  id: slugSchema,
  name: LocalizedTextSchema,
  description: LocalizedTextSchema.optional(),
  category: categoryPath,
  /** Search synonyms; also feed the text index. */
  tags: z.object({ ru: z.array(z.string()), en: z.array(z.string()) }),
  /** Tool classes the element is about (vocabulary in toolClasses.ts). */
  toolClasses: z.array(slugSchema),
  fitsTool: z.array(FitsToolSchema),
  footprint: FootprintSchema,
  bboxMm: BboxMmSchema,
  dimsMm: Vec3Schema,
  mounting: MountingSchema,
  /** Parameters of the generator that can rebuild this element at other dimensions (dimension widget). */
  params: z.array(ParamDefSchema).optional(),
  /** Sibling elements share a family (size ladders, A/B/C variants of one design). */
  family: slugSchema.optional(),
  /** Short label of this element inside its family, e.g. "6 slots, Ø8". */
  variantLabel: LocalizedTextSchema.optional(),
  generated: z.boolean(),
  assets: AssetsSchema,
  printNotes: PrintNotesSchema.optional(),
  provenance: ProvenanceSchema,
  license: LicenseSchema,
});
export type BankElement = z.infer<typeof BankElementSchema>;

export const BankCategorySchema = z.object({
  id: categoryPath,
  parent: categoryPath.optional(),
  name: LocalizedTextSchema,
  order: z.number().int(),
});
export type BankCategory = z.infer<typeof BankCategorySchema>;

export const ToolClassSchema = z.object({
  id: slugSchema,
  name: LocalizedTextSchema,
  /** Words that name this class in ru/en; the recogniser maps detector labels onto the class through them. */
  synonyms: z.object({ ru: z.array(z.string()), en: z.array(z.string()) }),
});
export type ToolClass = z.infer<typeof ToolClassSchema>;

export const BankCountsSchema = z.object({
  total: z.number().int(),
  /** Distinct elements that come from downloaded / project source files. */
  fromSources: z.number().int(),
  /** Elements produced by parametric generators (flag `generated`). */
  generated: z.number().int(),
  redistributable: z.number().int(),
});
export type BankCounts = z.infer<typeof BankCountsSchema>;

/**
 * An element the pipeline knows about but refused to publish because its files are missing or corrupt.
 * Never listed in `elements`; kept here so clients can say why a wall item cannot be drawn.
 */
export const UnavailableElementSchema = z.object({
  id: slugSchema,
  name: LocalizedTextSchema,
  /** Human-readable cause, e.g. `missing glb/0123456789abcdef.glb`. */
  reason: z.string().min(1),
});
export type UnavailableElement = z.infer<typeof UnavailableElementSchema>;

export const BankIndexSchema = z.object({
  version: z.literal(BANK_SCHEMA_VERSION),
  /** Hash over the content of all elements; used as the HTTP ETag of the index. */
  contentHash: sha256Hex,
  /** The honeycomb lattice the cell offsets refer to. */
  grid: z.object({ colPitchMm: z.number().positive(), rowPitchMm: z.number().positive() }),
  counts: BankCountsSchema,
  categories: z.array(BankCategorySchema),
  toolClasses: z.array(ToolClassSchema),
  elements: z.array(BankElementSchema),
  /** Elements withheld because their assets failed verification (absent when nothing was withheld). */
  unavailable: z.array(UnavailableElementSchema).optional(),
});
export type BankIndex = z.infer<typeof BankIndexSchema>;

/** Input of `POST /api/bank/elements/:id/variant`. */
export const VariantRequestSchema = z.object({ params: z.record(z.string(), z.number()) });
export type VariantRequest = z.infer<typeof VariantRequestSchema>;

export const VariantResponseSchema = z.object({
  /** URL of the meshopt GLB, immutable. */
  glbUrl: z.string(),
  bboxMm: BboxMmSchema,
  dimsMm: Vec3Schema,
  footprint: FootprintSchema,
  paramHash: z.string(),
  /** Values after clamping to the element's ParamDef ranges. */
  params: z.record(z.string(), z.number()),
  cached: z.boolean(),
});
export type VariantResponse = z.infer<typeof VariantResponseSchema>;

export function bankIndexJsonSchema(): unknown {
  return z.toJSONSchema(BankIndexSchema, { target: 'draft-2020-12' });
}
